import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as t,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Cursor 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/cursor/cursor-glossary.md","filePath":"zh/products/ai-coding/cursor/cursor-glossary.md","lastUpdated":1787110548000}'),a={name:"zh/products/ai-coding/cursor/cursor-glossary.md"};function n(d,r,c,g,p,l){return t(),o("div",null,[...r[0]||(r[0]=[s(`<h1 id="cursor-术语表" tabindex="-1">Cursor 术语表 <a class="header-anchor" href="#cursor-术语表" aria-label="Permalink to &quot;Cursor 术语表&quot;">​</a></h1><p>解释型文档：回答「是什么、为什么这样切、和谁容易混」。怎么配、怎么选见 <a href="./cursor-cheatsheet.html">速查表</a>；怎么点见 <a href="./cursor.html">教程</a>。</p><h2 id="概念关系图" tabindex="-1">概念关系图 <a class="header-anchor" href="#概念关系图" aria-label="Permalink to &quot;概念关系图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌──────────────┐</span></span>
<span class="line"><span>                    │  模型 + 工具  │</span></span>
<span class="line"><span>                    └──────┬───────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>              ┌────────────┼────────────┐</span></span>
<span class="line"><span>              │            │            │</span></span>
<span class="line"><span>         ┌────┴────┐  ┌───┴────┐  ┌────┴────┐</span></span>
<span class="line"><span>         │  Rules  │  │ Skills │  │   MCP   │</span></span>
<span class="line"><span>         │ AGENTS  │  │Commands│  │ (外部)  │</span></span>
<span class="line"><span>         └────┬────┘  └───┬────┘  └────┬────┘</span></span>
<span class="line"><span>              │           │            │</span></span>
<span class="line"><span>              └─────┬─────┴──────┬─────┘</span></span>
<span class="line"><span>                    │            │</span></span>
<span class="line"><span>              ┌─────┴─────┐ ┌────┴────┐</span></span>
<span class="line"><span>              │   Agent   │ │  Hooks  │  ← 观察 / 拦截循环</span></span>
<span class="line"><span>              │ Ask/Plan/ │ └─────────┘</span></span>
<span class="line"><span>              │ Debug/Tab │</span></span>
<span class="line"><span>              └─────┬─────┘</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>         ┌──────────┼──────────┐</span></span>
<span class="line"><span>         │                     │</span></span>
<span class="line"><span>   ┌─────┴─────┐        ┌──────┴──────┐</span></span>
<span class="line"><span>   │ Subagents │        │ Cloud /     │</span></span>
<span class="line"><span>   │  / CLI    │        │ Bugbot      │</span></span>
<span class="line"><span>   └───────────┘        └─────────────┘</span></span></code></pre></div><p><strong>怎么读</strong>：Rules / <code>AGENTS.md</code> 是常驻说明书。Skills / Commands 是按需工作流。MCP 把外部系统变成工具。Hooks 挂在循环上，不依赖模型自觉。Agent 在这些约束里选工具；Subagents 把吵的中间过程挪到别的上下文；Bugbot 和 Cloud 是仓库 / PR 维度的另一条线。</p><hr><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p><strong>是什么</strong>：写进模型上下文<strong>开头</strong>的持久指令。官方原文：模型跨补全不记事，Rules 在 prompt 层提供可复用上下文。</p><p><strong>为什么需要</strong>：没有它，你每次都要重复「用 pnpm」「别碰 <code>src/legacy</code>」。有它，团队把约定提交进 git，新会话自动带上。</p><p><strong>四种触发</strong>：Always / 按 glob / 按 description 智能拉取 / 仅 <code>@</code> 手动。frontmatter 真值表见 <a href="./cursor-cheatsheet.html#rules-frontmatter">速查表</a>。</p><p><strong>和 AGENTS.md 的区别</strong>：</p><table tabindex="0"><thead><tr><th></th><th>Rules (<code>.mdc</code>)</th><th>AGENTS.md</th></tr></thead><tbody><tr><td>格式</td><td>YAML frontmatter + Markdown</td><td>纯 Markdown</td></tr><tr><td>触发</td><td>四类</td><td>出现即作为项目指令</td></tr><tr><td>适合</td><td>按路径拆、要 metadata</td><td>简单、给人类和其他 Agent 看</td></tr></tbody></table><p><code>.cursor/rules</code> 里的纯 <code>.md</code> <strong>不会</strong>进规则系统。官方：若想写纯 Markdown，用 <code>AGENTS.md</code>。</p><p><strong>优先级</strong>：Team → Project → User。全部合并，冲突时更早的源优先。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/rules" target="_blank" rel="noreferrer">Rules</a></p><hr><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h2><p><strong>是什么</strong>：项目根或子目录里的一份普通 Markdown，写给 Agent 的说明书。没有 <code>description</code> / <code>globs</code> / <code>alwaysApply</code>。</p><p><strong>为什么需要</strong>：一份文件同时服务 Cursor、Claude Code、Codex 等读 <code>AGENTS.md</code> 的工具。Rules 的 glob 更强，但绑定 Cursor。</p><p><strong>在生态中的角色</strong>：简单项目可以只有它。复杂仓库：根目录 <code>AGENTS.md</code> 讲全局，<code>.cursor/rules/*.mdc</code> 按语言/目录加约束。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/rules" target="_blank" rel="noreferrer">Rules · AGENTS.md</a></p><hr><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p><strong>是什么</strong>：Agent Skills 开放标准下的目录：一份 <code>SKILL.md</code> + 可选 <code>scripts/</code> / <code>references/</code> / <code>assets/</code>。启动时被发现，Agent 按 <code>description</code> 判断是否相关；也可 <code>/skill-name</code> 手动调。</p><p><strong>为什么需要</strong>：Always Rules 每轮都占窗口。发布流程、评审清单这类长说明书应该按需加载。</p><p><strong>和 Commands 的区别</strong>：Commands 是「我键入 <code>/</code> 才跑」的 Markdown。Skills 默认可被模型自动调用；<code>disable-model-invocation: true</code> 时行为接近传统 slash command。官方 2.4 起有 <code>/migrate-to-skills</code>，把动态规则和 slash commands 迁过去。</p><p><strong>内置例子</strong>（官方表，不是完整产品功能列表）：<code>/create-rule</code>、<code>/create-skill</code>、<code>/create-subagent</code>、<code>/review-bugbot</code>、<code>/babysit</code>、<code>/in-cloud</code> 相关能力等。写文档前以 <a href="https://cursor.com/docs/skills" target="_blank" rel="noreferrer">Skills</a> 表格为准。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/skills" target="_blank" rel="noreferrer">Skills</a></p><hr><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p><strong>是什么</strong>：<code>.cursor/commands/</code> 或 <code>~/.cursor/commands/</code> 或 Dashboard Team Commands 里的 Markdown。聊天输入 <code>/</code> 列出。</p><p><strong>为什么需要</strong>：一天要跑很多次、步骤固定的提示（开 PR、修某个 issue 模板）。不必封装成带 scripts 的 Skill。</p><p><strong>官方状态</strong>：文档仍称 beta，语法可能变。不要宣布它已删除。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/context/commands" target="_blank" rel="noreferrer">Commands</a></p><hr><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p><strong>是什么</strong>：Model Context Protocol。Cursor 通过它调用外部工具和数据源。传输：<code>stdio</code>（本地进程）、<code>SSE</code>、<code>Streamable HTTP</code>。</p><p><strong>为什么需要</strong>：没有 MCP，你只能把 Figma JSON、Sentry 堆栈粘进 Chat。有 MCP，Agent 按需拉真实系统。</p><p><strong>和 Hooks 的区别</strong>：MCP 是「Agent 可以调用的工具」。Hooks 是「调用前后你的脚本」。两者常一起用：Hook 审计或拦截某个 MCP 工具。</p><p><strong>安全</strong>：MCP 能代表你执行代码、打外部 API。官方：只装可信源、最小权限 key、关键集成读源码。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/mcp" target="_blank" rel="noreferrer">MCP</a></p><hr><h2 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks&quot;">​</a></h2><p><strong>是什么</strong>：在 Agent / Tab / 工作区生命周期上拉起的进程，stdin/stdout 走 JSON。可观察、拦截、改行为。</p><p><strong>为什么需要</strong>：模型不会稳定地「每次都跑 prettier」或「永远别对生产库跑 SQL」。Hook 把策略放在循环外。</p><p><strong>三类</strong>：Agent 钩子、Tab 钩子、<code>workspaceOpen</code>。Cloud Agent 只跑仓库里的 command-based 钩子，原因见官方 Hooks 页（只读探索阶段不加载 hooks、没有 IDE 会话边界等）。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/hooks" target="_blank" rel="noreferrer">Hooks</a></p><hr><h2 id="subagents" tabindex="-1">Subagents <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;Subagents&quot;">​</a></h2><p><strong>是什么</strong>：父 Agent 可委派的专用助手。自己的上下文窗口，干完把结果交回。可前台阻塞或后台并行。</p><p><strong>为什么需要</strong>：官方根据「上下文被探索日志撑爆」的会话设计了三个内置子代理：</p><table tabindex="0"><thead><tr><th>子代理</th><th>干什么</th><th>为什么要独立</th></tr></thead><tbody><tr><td>Explore</td><td>搜和分析仓库</td><td>中间输出大；默认更快模型，可并行多次搜</td></tr><tr><td>Bash</td><td>一串 shell</td><td>日志吵</td></tr><tr><td>Browser</td><td>浏览器 MCP</td><td>DOM / 截图噪声大</td></tr></tbody></table><p><strong>和 Skills 怎么选</strong>（官方表）：要隔离上下文、并行、多步专长 → Subagent。单次可重复动作 → Skill。</p><p><strong>代价</strong>：每个子代理独立耗 token。简单活交给主 Agent 往往更快。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/subagents" target="_blank" rel="noreferrer">Subagents</a></p><hr><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><p><strong>是什么</strong>：同一 Agent 的不同约束，不是四个产品。</p><table tabindex="0"><thead><tr><th>模式</th><th>约束</th></tr></thead><tbody><tr><td>Agent</td><td>可以改文件、跑命令</td></tr><tr><td>Ask</td><td>只读理解（changelog：自带搜索，旧 <code>@Codebase</code> 工具已去掉）</td></tr><tr><td>Plan</td><td>先研究、提问、出可编辑计划，批准后再写</td></tr><tr><td>Debug</td><td>假设 → 埋点 → 你复现 → 用运行时数据修</td></tr></tbody></table><p><strong>为什么需要</strong>：默认 Agent 会尽快写代码。Plan 把「改什么」从「怎么改」里拆出来。Debug 避免在没证据时乱改。Ask 避免解释仓库时误伤文件。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/agent/overview" target="_blank" rel="noreferrer">Overview</a>、<a href="https://cursor.com/docs/agent/plan-mode" target="_blank" rel="noreferrer">Plan</a>、<a href="https://cursor.com/docs/agent/debug-mode" target="_blank" rel="noreferrer">Debug</a></p><hr><h2 id="tab" tabindex="-1">Tab <a class="header-anchor" href="#tab" aria-label="Permalink to &quot;Tab&quot;">​</a></h2><p><strong>是什么</strong>：补全专用模型。接受 <code>Tab</code>、拒绝 <code>Esc</code> 会成为后续建议的信号。</p><p><strong>为什么需要</strong>：多文件 Agent 对「改光标旁三行」又慢又贵。Tab 用最近编辑、lint、已接受建议做多行和跨文件预测。</p><p><strong>不是 Chat</strong>。没有工具循环，也不读你的整份 Rules 当一次「任务」。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/tab/overview" target="_blank" rel="noreferrer">Tab</a></p><hr><h2 id="bugbot" tabindex="-1">Bugbot <a class="header-anchor" href="#bugbot" aria-label="Permalink to &quot;Bugbot&quot;">​</a></h2><p><strong>是什么</strong>：对 PR（或 <code>/review-bugbot</code> 看到的本地 diff）做审查的云服务。找 bug、安全问题、质量问题，留言并给修复建议。</p><p><strong>为什么需要</strong>：人审 AI 生成的大 diff 会疲劳。Bugbot 每推一次跑一遍，并可按 <code>.cursor/BUGBOT.md</code> / Team rules 对齐仓库口味。</p><p><strong>不是 Debug Mode</strong>：Debug 在你的工作区里打日志、看运行时。Bugbot 看 diff，不启动你的 app。旧总览矩阵把 Bugbot 写成「带运行时上下文的自动调试器」，那是错的。</p><p><strong>Autofix</strong>：官方功能名。它再拉起一个 Cloud Agent 去改 finding。2026 文档没有名为 Fixer 的独立产品页。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/bugbot" target="_blank" rel="noreferrer">Bugbot</a></p><hr><h2 id="checkpoints" tabindex="-1">Checkpoints <a class="header-anchor" href="#checkpoints" aria-label="Permalink to &quot;Checkpoints&quot;">​</a></h2><p><strong>是什么</strong>：Agent 会话里、大改之前自动拍的工作区快照。时间线上可预览并 Restore。</p><p><strong>为什么需要</strong>：探索性和大重构需要可逆。Checkpoints 是文件级回滚，不是 git commit，也不是 Plan 文件。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/agent/overview" target="_blank" rel="noreferrer">Agent Overview · Checkpoints</a></p><hr><h2 id="codebase-indexing" tabindex="-1">Codebase Indexing <a class="header-anchor" href="#codebase-indexing" aria-label="Permalink to &quot;Codebase Indexing&quot;">​</a></h2><p><strong>是什么</strong>：把仓库切成函数/类级块，做成向量，用来做语义搜索。问「导航栏在哪」可以打到 <code>header.tsx</code>，即使文件名没有 navigation。</p><p><strong>为什么需要</strong>：单靠 grep 找不到同义词。官方：索引阶段算好向量，Agent 搜索更快、更省。</p><p><strong>隐私要点</strong>（官方）：路径加密；源码不以明文长期存放；索引过程中在内存处理。索引默认排除 <code>.gitignore</code> / <code>.cursorignore</code>。语义搜索约在索引 <strong>80%</strong> 完成后可用。闲置约 6 周会删索引。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/context/semantic-search" target="_blank" rel="noreferrer">Semantic search</a></p><hr><h2 id="privacy-mode" tabindex="-1">Privacy Mode <a class="header-anchor" href="#privacy-mode" aria-label="Permalink to &quot;Privacy Mode&quot;">​</a></h2><p><strong>是什么</strong>：数据治理开关。开启后，官方承诺 Cursor 和其他模型提供方<strong>不用你的代码训练</strong>。Enterprise 团队默认开。</p><p><strong>为什么需要</strong>：两路数据会离开本机：发给 LLM 的请求，以及（可选）Cloud Agents 为了改仓库而做的临时加密副本。Privacy Mode 管训练/留存承诺；它<strong>不是</strong>「代码永远不上网」。</p><p><strong>和 Cloud Agents</strong>：Cloud Agents 是官方写明「唯一需要 Cursor 存代码」的功能。策略禁止存代码就不要开 Cloud Agents，其余功能仍可用。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/enterprise/privacy-and-data-governance" target="_blank" rel="noreferrer">Privacy and Data Governance</a></p><hr><h2 id="cloud-agents" tabindex="-1">Cloud Agents <a class="header-anchor" href="#cloud-agents" aria-label="Permalink to &quot;Cloud Agents&quot;">​</a></h2><p><strong>是什么</strong>：在隔离 VM 上跑的 Agent。克隆仓库、建分支、干活、开 PR。可从编辑器 Cloud 下拉、<a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a>、<a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">手机</a>、Slack / GitHub / Linear <code>@cursor</code>、CLI 消息前加 <code>&amp;</code> 发起。</p><p><strong>曾用名</strong>：Background Agents（官方 Naming History）。新文档请用 Cloud Agents，不要再当两个产品写。</p><p><strong>为什么需要</strong>：不适合占着本地窗口的 todo 项：顺手修的 bug、补测试、文档、并行多条。对位 Claude 远程 / Dispatch、Gemini Jules。</p><p><strong>和本地 Subagents</strong>：本地子代理用你的机器和本机 MCP。Cloud 用团队在 cursor.com 配的 MCP 和环境。</p><p><strong>和 Bugbot</strong>：Cloud 是「去改仓库」；Bugbot 是「审 PR diff」。Autofix 才会从审查跳到 Cloud。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/cloud-agent" target="_blank" rel="noreferrer">Cloud Agent</a>、<a href="https://cursor.com/docs/cloud-agent/setup" target="_blank" rel="noreferrer">Setup</a>、<a href="https://cursor.com/blog/agent-best-practices" target="_blank" rel="noreferrer">agent-best-practices</a>。教程：<a href="./cloud-agents.html">Cloud Agents</a>。</p><hr><h2 id="cursor-cli" tabindex="-1">Cursor CLI <a class="header-anchor" href="#cursor-cli" aria-label="Permalink to &quot;Cursor CLI&quot;">​</a></h2><p><strong>是什么</strong>：官方终端入口，二进制名 <strong><code>agent</code></strong>。交互会话或 <code>agent -p</code> 无头 / CI。同一套 Agent 模式（Agent / Ask / Plan），读 <code>.cursor/rules</code>、<code>AGENTS.md</code>、<code>CLAUDE.md</code>。</p><p><strong>为什么需要</strong>：人已经在 SSH / tmux / CI 里时，不必为了同一套规则再开 GUI。CLI 不是第三个模型，是同一 Agent 的另一个表面。</p><p><strong>和编辑器 / Cloud</strong>：编辑器有 Tab 和 Inline Edit；CLI 没有。Cloud 跑在隔离 VM 上；CLI 默认改你当前工作目录（可用 <code>--worktree</code> 隔离）。会话里 <code>&amp;</code> 把当前任务交给 Cloud。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/cli/overview" target="_blank" rel="noreferrer">CLI Overview</a>、<a href="https://cursor.com/docs/cli/installation" target="_blank" rel="noreferrer">Installation</a>、<a href="https://cursor.com/docs/cli/headless" target="_blank" rel="noreferrer">Headless</a>。教程：<a href="./cursor-cli.html">Cursor CLI</a>。</p><hr><h2 id="design-mode" tabindex="-1">Design Mode <a class="header-anchor" href="#design-mode" aria-label="Permalink to &quot;Design Mode&quot;">​</a></h2><p><strong>是什么</strong>：Agents Window 浏览器里的视觉提示。点元素、多选、在冻结视口帧上画、或开口说。开关 <code>Cmd+Shift+D</code>。</p><p><strong>为什么需要</strong>：UI 改动是空间的。Agent 拿到元素身份（xpath、组件、计算样式、fiber props）再加一张截图，不只是一句话。</p><p><strong>和 Claude Design</strong>：这是叠在<em>你正在跑的应用</em>上的一层。<a href="./../claude/claude-design.html">Claude Design</a> 是独立的、跟品牌走的画布。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/agent/design-mode" target="_blank" rel="noreferrer">Design Mode</a>。教程：<a href="./design-mode.html">Design Mode</a>。</p><hr><h2 id="origin" tabindex="-1">Origin <a class="header-anchor" href="#origin" aria-label="Permalink to &quot;Origin&quot;">​</a></h2><p><strong>是什么</strong>：Cursor 的 git forge（early beta）。托管仓库、镜像 GitHub、在 <code>cursor.com/codebase</code> 浏览 / 搜索、开合并 PR。CLI 二进制是 <strong><code>origin</code></strong>，不是 <code>agent</code>。</p><p><strong>为什么需要</strong>：要 Cursor 托管的存储和 PR，而不只是 GitHub 上的审查评论。</p><p><strong>不是 Rules。</strong> 启用要先占用 <strong>codebase 名</strong>。只有 Pro / Teams / Enterprise。跟随 namespace owner 的 Privacy Mode。Legacy privacy 不能启用。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/origin" target="_blank" rel="noreferrer">Origin</a>。教程：<a href="./origin.html">Origin</a>。</p><hr><h2 id="security-agents" tabindex="-1">Security Agents <a class="header-anchor" href="#security-agents" aria-label="Permalink to &quot;Security Agents&quot;">​</a></h2><p><strong>是什么</strong>：Automations 上两个 Cursor 托管 Agent：<strong>Security Reviewer</strong>（PR / MR）和 <strong>Vulnerability Scanner</strong>（cron）。需要 Cloud Agents。本地技能：<code>/review-security</code>（Cursor 3.7+；CLI 即将到来）。</p><p><strong>为什么需要</strong>：专门的安全门禁和静止扫描，记在<strong>团队用量池</strong>、共享服务账号下。</p><p><strong>和 Bugbot</strong>：Bugbot 给通用 PR diff 留言。Security Agents 是另一组托管产品。PR Routing 可以读两边。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/security-agents" target="_blank" rel="noreferrer">Security Agents</a>。教程：<a href="./security-agents.html">Security Agents</a>。</p><hr><h2 id="pr-routing-approval" tabindex="-1">PR Routing &amp; Approval <a class="header-anchor" href="#pr-routing-approval" aria-label="Permalink to &quot;PR Routing &amp; Approval&quot;">​</a></h2><p><strong>是什么</strong>：Automations Agent，按所有权 / 提交史派审人，并可批准低风险 PR。政策文件必须精确叫 <code>APPROVAL_POLICY.md</code>。可选路由：<code>.cursor/approval-policies/ROUTING.md</code>。</p><p><strong>为什么需要</strong>：把对的人拉来审；只在政策允许处自动批。它<strong>不替代</strong>完整 code review。</p><p><strong>坑</strong>：文件名不对会被忽略。同一个 PR 里改政策，不能用新文本给这个 PR 放宽审查。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/approval-agents" target="_blank" rel="noreferrer">PR Routing &amp; Approval</a>。教程：<a href="./pr-routing.html">PR Routing</a>。</p><hr><h2 id="cursor-sdk" tabindex="-1">Cursor SDK <a class="header-anchor" href="#cursor-sdk" aria-label="Permalink to &quot;Cursor SDK&quot;">​</a></h2><p><strong>是什么</strong>：从你的进程调用同一套 Agent。TypeScript <code>@cursor/sdk</code>（Node 22.13+）、Python <code>cursor-sdk</code>（3.10+），其他语言走 <strong>SDK Bridge</strong>。运行时是 <code>local</code> 或 <code>cloud</code>；local 是循环 + 文件系统，<strong>不是</strong>本地模型。</p><p><strong>为什么需要</strong>：CI 机器人、分诊工人、产品内嵌 Agent、编排器。定价 / Privacy Mode 和 IDE、Cloud 一样；花费打在 <strong>SDK</strong> 标签下。</p><p><strong>密钥：</strong> 用户或服务账号。Team Admin API key 暂不支持。</p><p><strong>官方文档</strong>：<a href="https://cursor.com/docs/sdk/typescript" target="_blank" rel="noreferrer">TypeScript</a>、<a href="https://cursor.com/docs/sdk/python" target="_blank" rel="noreferrer">Python</a>、<a href="https://cursor.com/docs/sdk/bridge" target="_blank" rel="noreferrer">Bridge</a>。教程：<a href="./cursor-sdk.html">Cursor SDK</a>。</p>`,135)])])}const f=e(a,[["render",n]]);export{b as __pageData,f as default};
